```js
export function brickBounce(ball, overlapped) {
  // overlapped: array of brick rectangles
  let px = 0, py = 0, primary = null;
  for (const brick of overlapped) {
    const penL = (brick.x + brick.w) - (ball.x - ball.r);
    const penR = (ball.x + ball.r) - brick.x;
    const penX = Math.min(penL, penR);
    const penT = (brick.y + brick.h) - (ball.y - ball.r);
    const penB = (ball.y + ball.r) - brick.y;
    const penY = Math.min(penT, penB);
    const m = Math.min(penX, penY);
    if (!primary || m < primary.m) {
      primary = { penX, penY, m };
    }
  }
  // per primary face, flip velocity once and push out
  if (primary.penX < primary.penY) {
    // horizontal hit: flip vx
    ball.vx = -ball.vx;
    // push out horizontally toward the nearest face
    // figure direction: ball center relative to brick
    // we don't have the brick ref; push opposite to incoming direction
    if (ball.vx > 0) ball.x = ball.x + primary.penX; else ball.x = ball.x - primary.penX;
  } else if (primary.penY < primary.penX) {
    ball.vy = -ball.vy;
    if (ball.vy > 0) ball.y = ball.y + primary.penY; else ball.y = ball.y - primary.penY;
  } else {
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    ball.x = ball.x + (ball.vx > 0 ? primary.penX : -primary.penX);
    ball.y = ball.y + (ball.vy > 0 ? primary.penY : -primary.penY);
  }
  return primary;
}
```

