export function brickHit(ball, bricks) {
  const overlapped = bricks.filter(
    (b) => b.alive && collides(ball, b)
  );
  if (overlapped.length === 0) return overlapped;

  // Determine the face hit from the brick with the shallowest penetration
  // (the axis with the smallest overlap is the face that was struck).
  let primary = null;
