  state.ball.x = prevX + dx * (s / sub);
  state.ball.y = prevY + dy * (s / sub);

  const hits = brickBounce(state.ball, state.bricks);
  for (const brick of hits) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
