  const prevX = state.ball.prevX ?? state.ball.x;
  const prevY = state.ball.prevY ?? state.ball.y;
  const dx = state.ball.x - prevX;
  const dy = state.ball.y - prevY;
  const travel = Math.hypot(dx, dy);
  const sub = Math.max(1, Math.ceil(travel / BALL_R));

  let bounced = false;
  for (let s = 1; s <= sub && !bounced; s++) {
    state.ball.x = prevX + dx * (s / sub);
    state.ball.y = prevY + dy * (s / sub);

    const hits = brickBounce(state.ball, state.bricks);
    for (const brick of hits) {
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
    }
    if (hits.length > 0) bounced = true;
